---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Core binds
hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(terminal))   -- terminal
hl.bind(mainMod .. " + Q",      hl.dsp.window.close())        -- close window
hl.bind(mainMod .. " + W",      hl.dsp.window.close())        -- close window (alt)
hl.bind(mainMod .. " + B",      hl.dsp.exec_cmd(browser))     -- default browser
hl.bind(mainMod .. " + M",      hl.dsp.exec_cmd("hyprctl dispatch exit")) -- exit hyprland
hl.bind(mainMod .. " + E",      hl.dsp.exec_cmd(fileManager)) -- file manager
hl.bind(mainMod .. " + R",      hl.dsp.exec_cmd(menu))        -- app launcher
hl.bind(mainMod .. " + V",      hl.dsp.window.float({ action = "toggle" })) -- toggle float
hl.bind(mainMod .. " + D",      hl.dsp.exec_cmd("/home/kavin/.config/hypr/scripts/show-desktop.sh")) -- show desktop

-- Window management
hl.bind(mainMod .. " + P",      hl.dsp.window.pseudo())       -- dwindle pseudo
hl.bind(mainMod .. " + J",      hl.dsp.layout("togglesplit")) -- dwindle toggle split
hl.bind("ALT + space",           hl.dsp.exec_cmd(menu))        -- app launcher (walker)
hl.bind(mainMod .. " + space",   hl.dsp.exec_cmd(menu))        -- app launcher (walker)
hl.bind(mainMod .. " + TAB",    hl.dsp.exec_cmd("hyprctl dispatch swapwithmaster")) -- swap with master

-- Move focus with mainMod + HJKL (vim-style)
hl.bind(mainMod .. " + h",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + l",  hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + k",  hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + j",  hl.dsp.focus({ direction = "down" }))

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- Fullscreen & layout
hl.bind(mainMod .. " + F",           hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" })) -- fullscreen
hl.bind(mainMod .. " + SHIFT + F",   hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" })) -- maximize

-- Alt keybinds
hl.bind("ALT + Return",              hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" })) -- maximize

-- Alt+Tab window switching with snappy-switcher
hl.bind("ALT + Tab",                 hl.dsp.exec_cmd("snappy-switcher next --mod alt"))
hl.bind("ALT + SHIFT + Tab",         hl.dsp.exec_cmd("snappy-switcher prev --mod alt"))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", function() hl.dispatch(hl.dsp.window.drag()) end,   { mouse = true })
hl.bind(mainMod .. " + mouse:273", function() hl.dispatch(hl.dsp.window.resize()) end, { mouse = true })

-- Trackpad-friendly: use keyboard keys instead of mouse clicks
hl.bind(mainMod .. " + Control_L", function() hl.dispatch(hl.dsp.window.drag()) end,   { mouse = true })
hl.bind(mainMod .. " + Alt_L",     function() hl.dispatch(hl.dsp.window.resize()) end, { mouse = true })

-- Windows-style workspace switching: Win + Ctrl + Left/Right
hl.bind(mainMod .. " + CTRL + left",  hl.dsp.focus({ workspace = "e-1" }))
hl.bind(mainMod .. " + CTRL + right", hl.dsp.focus({ workspace = "e+1" }))

-- Move window to prev/next workspace: Win + Shift + Left/Right
hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.window.move({ workspace = "e-1" }))
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.window.move({ workspace = "e+1" }))

-- Create new workspace: Win + Ctrl + D
hl.bind(mainMod .. " + CTRL + D", hl.dsp.exec_cmd("~/.config/hypr/scripts/workspace-new.sh"))

-- Close current workspace: Win + Ctrl + F4
hl.bind(mainMod .. " + CTRL + F4", hl.dsp.exec_cmd("~/.config/hypr/scripts/workspace-close.sh"))

-- Quick workspace navigation (bracket keys as alt)
hl.bind(mainMod .. " + bracketleft",  hl.dsp.focus({ workspace = "e-1" }))
hl.bind(mainMod .. " + bracketright", hl.dsp.focus({ workspace = "e+1" }))

-- Scratchpad (Win + S)
hl.bind(mainMod .. " + S", hl.dsp.workspace.toggle_special("magic"))

-- Screenshot (Win + Shift + S)
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.exec_cmd("~/.config/hypr/scripts/screenshot-ksnip.sh"))

-- Keep workspaces 1-5 alive even when empty
for i = 1, 5 do
    hl.workspace_rule({ workspace = tostring(i), persistent = true })
end

-- Create 5 persistent workspaces at startup
hl.on("hyprland.start", function ()
    hl.exec_cmd("hyprctl dispatch 'hl.dsp.focus({workspace=\"2\"})'")
    hl.exec_cmd("hyprctl dispatch 'hl.dsp.focus({workspace=\"3\"})'")
    hl.exec_cmd("hyprctl dispatch 'hl.dsp.focus({workspace=\"4\"})'")
    hl.exec_cmd("hyprctl dispatch 'hl.dsp.focus({workspace=\"5\"})'")
    hl.exec_cmd("hyprctl dispatch 'hl.dsp.focus({workspace=\"1\"})'")
end, { once = true })

-- Switch workspaces with mainMod + [1-5]
-- Move active window to a workspace with mainMod + SHIFT + [1-5]
hl.bind(mainMod .. " + 1", hl.dsp.exec_cmd("hyprctl dispatch 'hl.dsp.focus({workspace=\"1\"})'"))
hl.bind(mainMod .. " + 2", hl.dsp.exec_cmd("hyprctl dispatch 'hl.dsp.focus({workspace=\"2\"})'"))
hl.bind(mainMod .. " + 3", hl.dsp.exec_cmd("hyprctl dispatch 'hl.dsp.focus({workspace=\"3\"})'"))
hl.bind(mainMod .. " + 4", hl.dsp.exec_cmd("hyprctl dispatch 'hl.dsp.focus({workspace=\"4\"})'"))
hl.bind(mainMod .. " + 5", hl.dsp.exec_cmd("hyprctl dispatch 'hl.dsp.focus({workspace=\"5\"})'"))
hl.bind(mainMod .. " + SHIFT + 1", hl.dsp.exec_cmd("hyprctl dispatch 'hl.dsp.window.move({workspace=\"1\"})'"))
hl.bind(mainMod .. " + SHIFT + 2", hl.dsp.exec_cmd("hyprctl dispatch 'hl.dsp.window.move({workspace=\"2\"})'"))
hl.bind(mainMod .. " + SHIFT + 3", hl.dsp.exec_cmd("hyprctl dispatch 'hl.dsp.window.move({workspace=\"3\"})'"))
hl.bind(mainMod .. " + SHIFT + 4", hl.dsp.exec_cmd("hyprctl dispatch 'hl.dsp.window.move({workspace=\"4\"})'"))
hl.bind(mainMod .. " + SHIFT + 5", hl.dsp.exec_cmd("hyprctl dispatch 'hl.dsp.window.move({workspace=\"5\"})'"))

-- Scroll through workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("/home/kavin/.config/hypr/scripts/osd-volume.sh up"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("/home/kavin/.config/hypr/scripts/osd-volume.sh down"), { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("/home/kavin/.config/hypr/scripts/osd-volume.sh mute"), { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("pactl set-source-mute @DEFAULT_SOURCE@ toggle"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("/home/kavin/.config/hypr/scripts/osd-brightness.sh up"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("/home/kavin/.config/hypr/scripts/osd-brightness.sh down"),                  { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


